	ok: number,
	/**  3 checks per URL target of `targets.txt`: 36 with Flowseal's file. */
	total: number,
	errors: number,
	ssl: number,
	unsup: number,
	/**  Median `time_total` of the checks that passed. */
	median_ms: number | null,
	ping_ok: number,
	ping_total: number,
	ping_median_ms: number | null,
	fail: number,
	likely_blocked: number,
	discord: ProfileScore,
	youtube: ProfileScore,
	/**  The DbD game server (`rank::DBD`). Runs from before 0.9.0 counted Steam and Epic here too. */
	dbd: ProfileScore,
	steam?: ProfileScore,
	epic?: ProfileScore,
