export type TurnOffTarget = 
/**  The zapret service. */
"zapret" | 
/**  Whatever the culprit goes through now: the zapret strategy or a routing rule. */
"current";

/**  The run's answer in one code (proposal 2). */
export type VerdictCode = 
/**  Nothing seen: the program opened no connections while watched. */
"no_flows" | 
/**  The program was not in the state the profile needs (Discord not running, not in voice). */
"not_reproducible" | 
/**  Everything seen worked, and everything that matters was seen. */
"clean" | 
/**  Nothing failed, but part of the traffic or the client state was not seen. */
"inconclusive" | 
/**  Culprits, and a path that fixes every one of them. */
"culprits_fixed" | 
/**  Culprits, some fixed. */
"culprits_partial" | 
/**  Culprits, none fixed. */
"culprits_unfixed" | 
/**  Direct flows pass; what goes through the system proxy fails the way NekoBox sends it (Р1). */
"proxy_broken" | 
/**  The problem is on the other side (a peer, the service). */
"peer_side" | 
/**  A whitelist network (Р5). */
"whitelist" | 
/**  A live-only profile in auto mode. */
"live_only";

export type Via = { via: "Opening" } | { via: "Proxy" } | { via: "Direct"; reason: DirectReason };

/**  Where Discord's voice got to, from its own logs (proposal 3). */
export type VoiceStage = 
/**  No voice session in the logs. */
"none" | 
/**  Joined, but no voice server came (gateway side). */
"no_endpoint" | 
/**  The voice WebSocket did not connect. */
"ws_failed" | 
/**  The WebSocket connected, UDP did not. */
"udp_failed" | 
/**  Connected; DAVE waits for a second participant (normal when alone). */
"dave_waiting_peer" | 
/**  Connected; DAVE stalled with others present. */
"dave_stalled" | "connected";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

